#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t ;    cin >> t;    while (t--) {        long long n , k , q ;        cin >> n >> k >> q;         vector<long long> a(n);         for(int i = 0 ; i < n ; i++)        {            cin >> a[i];            a[i] = (a[i]> q) ? 0 : 1;         }     long long count_of_1 = 0;    long long ways = 0;     for(int i = 0;i<n ; i++)    {        if(a[i] == 1)        {            count_of_1++;         }    else    {        if(count_of_1 >= k)        {            long long diff = count_of_1 -k + 1;            ways += (diff*(diff + 1))/2;         }     count_of_1 = 0;}}if(count_of_1 >= k){    long long diff = count_of_1 - k + 1;    ways += (diff*(diff + 1))/2;} cout << ways << endl;}return 0;}